-- ===== Leonida in motion: imagery, local reel and editorial copy =====
-- Mirrors database/migrations/004_leonida_in_motion.sql.
AS new ON DUPLICATE KEY UPDATE
    title = new.title, media_type = new.media_type, intended_use = new.intended_use,
    source_url = new.source_url, embed_url = new.embed_url, local_path = new.local_path,
    attribution = new.attribution, usage_status = new.usage_status, approval_status = new.approval_status,
    notes = new.notes;



UPDATE media_assets SET local_path = 'clips/jason-duval.mp4' WHERE slug = 'clip-jason-duval';
UPDATE media_assets SET local_path = 'clips/lucia-caminos.mp4' WHERE slug = 'clip-lucia-caminos';
UPDATE media_assets SET local_path = 'clips/cal-hampton.mp4' WHERE slug = 'clip-cal-hampton';
UPDATE media_assets SET local_path = 'clips/boobie-ike.mp4' WHERE slug = 'clip-boobie-ike';
UPDATE media_assets SET local_path = 'clips/dre-quan-priest.mp4' WHERE slug = 'clip-dequan-priest';
UPDATE media_assets SET local_path = 'clips/real-dimez.mp4' WHERE slug = 'clip-real-dimez';
UPDATE media_assets SET local_path = 'clips/raul-bautista.mp4' WHERE slug = 'clip-raul-bautista';
UPDATE media_assets SET local_path = 'clips/brian-heder.mp4' WHERE slug = 'clip-brian-heder';
UPDATE characters SET summary = 'A former soldier working for drug runners in the Keys, looking for an easier life.', biography = 'Jason grew up around grifters and crooks, spent a stint in the Army trying to shake off a troubled youth, and ended up in the Keys doing what he knows best: working for local drug runners. All he wants is an easy life, but things keep getting harder.' WHERE slug = 'jason-duval' AND content_status = 'official';
UPDATE characters SET summary = 'Fresh out of Leonida Penitentiary and set on changing the odds.', biography = 'Lucia''s father taught her to fight as soon as she could walk, and life has been coming at her swinging ever since. Fighting for her family landed her in the Leonida Penitentiary. Now she is out, with a plan to change the odds in her favour and no intention of letting anything stand in the way.' WHERE slug = 'lucia-caminos' AND content_status = 'official';
UPDATE characters SET summary = 'Jason''s friend, and happiest at home with the Coast Guard radio on.', biography = 'A friend of Jason''s and another of Brian''s associates, Cal feels safest at home with a few beers, listening in on Coast Guard chatter and chasing conspiracy theories online.' WHERE slug = 'cal-hampton' AND content_status = 'official';
UPDATE characters SET summary = 'A Vice City legend who turned a street education into businesses.', biography = 'Boobie Ike turned his experience of the street into legitimate enterprises, from real estate to a strip club and a recording studio. His latest partnership is with Dre''Quan Priest at Only Raw Records.' WHERE slug = 'boobie-ike' AND content_status = 'official';
UPDATE characters SET summary = 'A hustler turned music mogul behind Only Raw Records.', biography = 'Dre''Quan left street dealing behind to found Only Raw Records. He now manages the rap duo Real Dimez, and partners with Boobie Ike.' WHERE slug = 'dre-quan-priest' AND content_status = 'official';
UPDATE characters SET summary = 'A seasoned bank robber who keeps raising the stakes.', biography = 'Raul assembles talented crews for high-reward heists, and the stakes climb with every job.' WHERE slug = 'raul-bautista' AND content_status = 'official';
UPDATE characters SET summary = 'A veteran smuggler from the Keys'' golden age.', biography = 'Brian is a classic drug runner who works out of a boat yard with his wife Lori. He gives Jason a place to live, as long as Jason helps out with the odd shakedown and stops by for Lori''s sangria.' WHERE slug = 'brian-heder' AND content_status = 'official';
UPDATE characters SET summary = 'Two high school friends turned rap duo, signed to Only Raw Records.', biography = 'Bae-Luxe and Roxy turned their street activity into rap tracks and a social media following, then signed with Dre''Quan Priest''s Only Raw Records.' WHERE slug = 'real-dimez' AND content_status = 'official';
UPDATE regions SET summary = 'The neon-lit city at the heart of Leonida.', description = 'Vice City is the neon-soaked urban heart of Leonida and the home turf of Boobie Ike, whose businesses range from real estate to a recording studio.' WHERE slug = 'vice-city' AND content_status = 'official';
UPDATE regions SET summary = 'Island life, boats and smugglers.', description = 'The Keys are where Jason works for local drug runners and where Brian Heder keeps his boat yard.' WHERE slug = 'leonida-keys' AND content_status = 'official';
UPDATE regions SET summary = 'Wetlands, airboats and Real Dimez''s turf.', description = 'Grassrivers is the wetland region Rockstar associates with the rap duo Real Dimez.' WHERE slug = 'grassrivers' AND content_status = 'official';
UPDATE regions SET summary = 'Raul Bautista''s heist country.', description = 'Port Gellhorn is the region Rockstar connects with bank robber Raul Bautista and his ever-bigger heists.' WHERE slug = 'port-gellhorn' AND content_status = 'official';
UPDATE regions SET summary = 'Industrial skylines and long sunsets.', description = 'Ambrosia is one of the six regions of Leonida. Rockstar has shared few details about it so far.' WHERE slug = 'ambrosia' AND content_status = 'official';
UPDATE regions SET summary = 'National park country: forest, canyon roads and rivers.', description = 'Mount Kalaga National Park is the wild corner of Leonida, where Rockstar''s screenshots show forest trails, a canyon road and river paddling.' WHERE slug = 'mount-kalaga' AND content_status = 'official';
UPDATE vehicles SET summary = 'A sleek white sports coupe from the Ultimate Edition screenshots.', description = 'The ''95 Grotti Cheetah appears in four official screenshots, from a sunlit car park to a close-up of its red interior.' WHERE slug = 'grotti-cheetah' AND content_status = 'official';
UPDATE vehicles SET summary = 'A Dominator rebuilt as an off-road buggy.', description = 'The ''67 Vapid Dominator Buggy is a muscle car converted for mud and dirt, shown on a trail and in close-up.' WHERE slug = 'vapid-dominator-buggy' AND content_status = 'official';
UPDATE vehicles SET summary = 'A speedboat shown on the water around Vice City.', description = 'The Shitzu Squalo appears by day and at night, cutting across the bay with the skyline behind it.' WHERE slug = 'shitzu-squalo' AND content_status = 'official';
UPDATE vehicles SET summary = 'A classic sedan from the Vintage Vice City Pack.', description = 'The Vapid Stanier is a vintage cruiser shown in four official images, glowing under the lights of the Vice City streets.' WHERE slug = 'vapid-stanier' AND content_status = 'official';
UPDATE vehicles SET summary = 'A retro muscle pickup, parked by the waterfront.', description = 'The Vapid Ganado Retro Build appears in one official image: a bright, low-slung pickup with racing stripes.' WHERE slug = 'vapid-ganado' AND content_status = 'official';
UPDATE character_relationships cr JOIN characters fa ON fa.character_id = cr.from_character_id JOIN characters fb ON fb.character_id = cr.to_character_id SET cr.description = 'The two leads of the story.' WHERE fa.slug = 'jason-duval' AND fb.slug = 'lucia-caminos' AND cr.content_status = 'official';
UPDATE character_relationships cr JOIN characters fa ON fa.character_id = cr.from_character_id JOIN characters fb ON fb.character_id = cr.to_character_id SET cr.description = 'Brian gives Jason a place to live in return for his help.' WHERE fa.slug = 'brian-heder' AND fb.slug = 'jason-duval' AND cr.content_status = 'official';
UPDATE character_relationships cr JOIN characters fa ON fa.character_id = cr.from_character_id JOIN characters fb ON fb.character_id = cr.to_character_id SET cr.description = 'Cal is a friend of Jason''s.' WHERE fa.slug = 'cal-hampton' AND fb.slug = 'jason-duval' AND cr.content_status = 'official';
UPDATE character_relationships cr JOIN characters fa ON fa.character_id = cr.from_character_id JOIN characters fb ON fb.character_id = cr.to_character_id SET cr.description = 'Partners at Only Raw Records.' WHERE fa.slug = 'boobie-ike' AND fb.slug = 'dre-quan-priest' AND cr.content_status = 'official';

